    public Claim save(Claim claim) {
        if (claim.id() != null) {
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ? WHERE id = ? AND sheet_id = ?",
                    claim.amount(), Date.valueOf(claim.date()), claim.note(), claim.id(), claim.sheetId());
            return claim;
